  "summary": "The code suffered from manual CSV generation, lack of type safety, and side-effect-heavy mutation of input arguments. I have refactored the CSV logic to use the standard library, added type hints, and ensured input data is not mutated by returning new objects.",
  "fixed_code": "import csv\nimport io\nimport copy\nfrom collections import defaultdict\nfrom typing import List, Dict, Any\n\ndef attach_orders(users: List[Dict[str, Any]], orders: List[Dict[str, Any]]) -> List[Dict[str, Any]]:\n    \"\"\"Attach orders to their respective users based on user_id.\"\"\"\n    by_user = defaultdict(list)\n    for order in orders:\n        uid = order.get(\"user_id\")\n        if uid is not None:\n            by_user[uid].append(order)\n    \n    new_users = copy.deepcopy(users)\n    for user in new_users:\n        user[\"orders\"] = by_user.get(user.get(\"id\"), [])\n    return new_users\n\ndef dedupe_orders(orders: List[Dict[str, Any]]) -> List[Dict[str, Any]]:\n    \"\"\"Remove duplicate orders based on order ID.\"\"\"\n    seen = set()\n    unique = []\n    for order in orders:\n        if order.get(\"id\") not in seen:\n            seen.add(order[\"id\"])\n            unique.append(order)\n    return unique\n\ndef render_csv(header: List[str], rows: List[List[Any]]) -> str:\n    \"\"\"Render data to CSV format safely.\"\"\"\n    output = io.StringIO()\n    writer = csv.writer(output)\n    writer.writerow(header)\n    \n    for row in rows:\n        sanitized_row = []\n        for cell in row:\n            s_cell = str(cell)\n            if s_cell.startswith(('=', '+', '-', '@')):\n                s_cell = \"'\" + s_cell\n            sanitized_row.append(s_cell)\n        writer.writerow(sanitized_row)\n        \n    return output.getvalue()"
